  "scienceLead": "\u0909\u0938\u0940 \u0938\u0902\u0930\u0915\u094d\u0937\u0923, \u0905\u0928\u0941\u092e\u0924\u093f \u0914\u0930 \u0926\u094d\u0935\u093e\u0930\u094b\u0902 \u0915\u0947 \u0905\u0927\u0940\u0928 \u0938\u093e\u0930\u094d\u0935\u091c\u0928\u093f\u0915 \u0938\u0939\u094b\u0926\u0930 \u092d\u0902\u0921\u093e\u0930\u0964 \u0916\u0941\u0932\u093e \u0936\u094b\u0927 \u0914\u0930 \u092a\u094d\u0930\u0923\u093e\u0932\u0940 \u0905\u092d\u093f\u092f\u093e\u0902\u0924\u094d\u0930\u093f\u0915\u0940 \u2014 \u0915\u093e\u0930\u0916\u093e\u0928\u0947 \u092f\u093e \u092a\u094d\u0930\u092e\u093e\u0923\u093f\u0924 \u0935\u093e\u092f\u0941\u092f\u093e\u0928 \u0928\u0939\u0940\u0902\u0964",
