  "scienceProteinNote": "de-novo \u0921\u093f\u091c\u093c\u093e\u0907\u0928 \u0915\u0947 \u0932\u093f\u090f \u0938\u093e\u0930\u094d\u0935\u091c\u0928\u093f\u0915 \u0936\u094b\u0927 \u091c\u093e\u0932\u0940\u0964 \u091a\u093f\u0915\u093f\u0924\u094d\u0938\u0940\u092f \u0928\u0939\u0940\u0902\u0964 \u0917\u0940\u0932\u0940-\u092a\u094d\u0930\u092f\u094b\u0917\u0936\u093e\u0932\u093e \u0909\u0924\u094d\u092a\u093e\u0926 \u0928\u0939\u0940\u0902\u0964",
  "scienceMercy": "Mercy Coordination Substrate",
