  "faqContact": "\u092a\u094d\u0930\u0936\u094d\u0928: <a href=\"mailto:info@Rathor.ai\" class=\"text-amber-300 hover:text-amber-200\">info@Rathor.ai</a>\u0964",
  "watchTitle": "\u0928\u093f\u0930\u0940\u0915\u094d\u0937\u0923 \u0935\u0930\u094d\u0917 \u2014 1 \u0938\u093f\u0924\u0902\u092c\u0930 2026",
  "watchLead": "\u092c\u093e\u0939\u0930\u0940 \u0926\u093e\u0935\u0947 \u0926\u0930\u094d\u091c \u0924\u093e\u0915\u093f \u0936\u0940\u0930\u094d\u0937\u0915 \u0905\u0928\u0941\u092e\u0924\u093f-\u092e\u093e\u0928 \u092f\u093e \u0935\u0902\u0936 \u0928 \u092c\u0928 \u091c\u093e\u090f\u0901\u0964 \u0909\u0924\u094d\u092a\u093e\u0926 \u0928\u0939\u0940\u0902\u0964",
